import{_ as r,o,c as a,a2 as s}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"通用","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/general.md","filePath":"zh-HK/user-guide/settings/general.md","lastUpdated":1786795875000}'),e={name:"zh-HK/user-guide/settings/general.md"};function n(i,t,l,g,h,p){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="通用" tabindex="-1">通用 <a class="header-anchor" href="#通用" aria-label="Permalink to &quot;通用&quot;">​</a></h1><p>六個 Tab:<strong>系統</strong>、<strong>快速搜尋視窗</strong>、<strong>完整搜尋視窗</strong>、<strong>預覽視窗</strong>、<strong>快速導航</strong>、<strong>預覽與縮略圖</strong>。</p><h2 id="系統" tabindex="-1">系統 <a class="header-anchor" href="#系統" aria-label="Permalink to &quot;系統&quot;">​</a></h2><ul><li><strong>開機自動啓動 Lertaro</strong> —— 核取方塊，登錄時自動啓動。</li><li><strong>啓動時自動檢查更新</strong> —— 核取方塊。</li><li><strong>自動靜默更新</strong> —— 核取方塊，僅在上面的選項開啓時可用；檢測到新版本時在後臺靜默下載安裝，不彈窗提示。</li><li><strong>啓用硬件加速</strong> —— 核取方塊，預設開啓。關閉後會讓快速搜尋視窗改用軟件渲染而不是 Direct3D——用來解決 NVIDIA Advanced Optimus 因為 Lertaro 在運行而拒絕切換顯卡的問題(只影響快速視窗，不影響整個 App)。需要重啓 Lertaro 才能生效。</li><li><strong>隱藏系統匣圖示</strong> —— 核取方塊，預設關閉。立即生效，不需要重啓。不管這個設定開不開，<a href="./../hotkeys.html#搜尋框圖示">快速視窗自帶的圖示</a>始終能打開和系統匣圖示右鍵一樣的選單，所以隱藏系統匣圖示不會讓你找不到設定或退出的入口。</li><li><strong>在檔案總管新索引標籤中開啓資料夾</strong> —— 核取方塊，預設關閉。在 Windows 11 上，已有原生檔案總管視窗時，<strong>開啓</strong>和<strong>開啓所在資料夾</strong>都會在新索引標籤中開啓；後者還會選取目標項目。沒有檔案總管視窗時，Windows 會先以普通視窗開啓第一項，之後的項目才會使用索引標籤。這項實驗性整合在設定第三方檔案管理器時不會生效。</li><li><strong>啓用模糊匹配</strong> —— 核取方塊，預設開啓。開啓時，普通查詢詞只要字元按順序出現在名稱中任意位置就能命中；關閉後，普通查詢詞必須作為連續子串出現(<code>abc</code> 不再匹配 <code>a-b-c</code>)——哪些不受影響見<a href="./../search-syntax.html#模糊匹配-預設">搜尋語法</a>。立即生效，不需要重啓。</li><li><strong>查詢標記總前導字元</strong> —— 文字方塊（最多 1 個字元，預設為 <code>:</code>）。設定搜尋框尾部切分標記運算式的總前導字元。動態路徑過濾與自訂分類過濾插件前綴可在 <strong>設定 → 插件 → CoreExtensions</strong> 中獨立設定。</li><li><strong>日誌等級</strong> —— 下拉式方塊:錯誤 / 警告 / 信息(預設)/ 調試。控制 App、Service、Hook 三處日誌(見<a href="./service-status.html">運行狀態</a>)的詳細程度。</li><li><strong>介面語言</strong> —— 下拉式方塊，內容來自所有已安裝的語言包提供者(內置語言加上任何插件新增的語言)。</li></ul><p>主題選擇已經移到獨立的<a href="./appearance.html">外觀</a>分區——主題選擇器和&quot;跟隨系統淺色/深色設定&quot;選項都在那一頁。</p><h2 id="快速搜尋視窗" tabindex="-1">快速搜尋視窗 <a class="header-anchor" href="#快速搜尋視窗" aria-label="Permalink to &quot;快速搜尋視窗&quot;">​</a></h2><p>涵蓋快速搜尋欄的外觀佈局，以及它搜尋結果的類型優先級。</p><p><strong>搜尋欄佈局</strong> —— 自訂快速搜尋欄的大小以及螢幕顯示位置:</p><ul><li><strong>搜尋欄寬度(像素)</strong> —— 範圍 300–1200px，預設 570px。</li><li><strong>搜尋欄高度(像素)</strong> —— 範圍 45–120px，預設 60px。這一個數值同時驅動結果行的圖示大小、名稱/ 路徑字型大小和行高(<code>高度 / 60</code>)，所以搜尋欄調高，整個結果列表也會跟着放大，圖示和文字始終保持同樣的比例。</li><li><strong>搜尋框內顯示時鐘</strong> —— 核取方塊，預設關閉。開啓後，當搜尋框為空時會用當前日期、星期幾和時間替換掉原本的&quot;輸入以搜尋...&quot;提示文字。一開始輸入內容，時鐘就會和提示文字一樣消失。只影響快速視窗——內聯視窗不管這個設定開沒開，都保持它自己原本的提示文字。</li><li><strong>再次按下快速鍵時打開完整視窗</strong> —— 核取方塊，預設關閉。正常情況下，快速視窗已經打開時再按一次呼出熱鍵只會隱藏它；開啓這個選項後，第二次按下會改為切換到完整視窗(帶上已經輸入的查詢內容)，而不是直接關閉。</li><li><strong>鎖定位置</strong> —— 核取方塊，預設關閉。開啓後不允許拖動快速視窗，避免誤按把它挪離你放好的位置。右鍵點擊 logo 仍然可以重置位置；下面的<strong>重置佈局設定</strong>也會連同這個鎖一起清掉。</li><li><strong>重置佈局設定</strong> 按鈕 —— 把以上五項都恢復為預設值。</li></ul><p>在<a href="./../hotkeys.html#搜尋框圖示">快速視窗的圖示</a>上右鍵，可以單獨重置它的螢幕位置(不影響大小)，效果和首次啓動時的居中方式一樣。</p><p><strong>結果類型優先級</strong> —— 跟下面<a href="#快速導航">快速導航</a>同一套上移/下移(也可以拖動)排序列表：把某個結果類型(應用程式、系統設定、檔案過濾器、任何第三方插件自己提供的可搜尋項，或內置的&quot;檔案&quot;條目)上移，就能讓它在快速視窗的結果裏始終排在下面的類型前面，不管實際上誰的文本匹配得更好。歷史記錄和收藏夾始終排最前，不受這個列表影響。</p><p>每個類型還可以單獨配一個單字元<strong>觸發符</strong>(可選，每行一個輸入框)：在快速視窗裏把這個字元打在最前面，就只會顯示這個類型的結果，其他全部隱藏——具體例子見<a href="./../search-syntax.html#結果類型觸發符">搜尋語法</a>。只打觸發符、後面還沒打內容時，會顯示&quot;繼續輸入以只搜尋……&quot;這樣的提示，而不是&quot;無搜尋結果&quot;。挑一個平時正常搜尋絕對不會以它開頭的字元，因為一旦分配給某個類型，這個字元就等於被佔用了——建議用標點符號(比如 <code>;</code>)而不是純空格，因為只打一個空格、後面沒有內容時會被當成搜尋框為空處理，不會顯示這個提示。</p><h2 id="完整搜尋視窗" tabindex="-1">完整搜尋視窗 <a class="header-anchor" href="#完整搜尋視窗" aria-label="Permalink to &quot;完整搜尋視窗&quot;">​</a></h2><p>設定完整/主搜尋視窗(從工作列或開始功能表捷徑打開的那個更大的視窗，區別於快速彈出搜尋欄——見<a href="./../getting-started.html#三種視窗">快速上手</a>)的預設大小:</p><ul><li><strong>視窗寬度(像素)</strong> —— 範圍 640–2000px，預設 854px。</li><li><strong>視窗高度(像素)</strong> —— 範圍 400–1400px，預設 480px。這兩個下限分別對應視窗自身可拖曳調整的最小尺寸，所以配置的值不會被視窗自己悄悄覆蓋。</li><li><strong>重置搜尋視窗設定</strong> 按鈕。</li><li><strong>僅允許一個完整搜尋視窗</strong> —— 核取方塊，預設關閉。關閉時可以同時打開多個相互獨立的完整視窗；啟用後，再次打開完整視窗會啟用已有視窗而不是建立新視窗。快速視窗透過<strong>顯示更多</strong>攜帶查詢切換過來時，該查詢會取代已有視窗中的查詢。</li></ul><p>手動拖曳視窗邊緣調整大小時會自動記住這個尺寸——下次打開視窗(或新開一個)時會沿用上次離開時的大小，本頁面上的數值也會同步更新。在視窗處於最大化狀態時調整不會覆蓋已記住的尺寸，只有在正常(非最大化)狀態下調整才會被記住。</p><p>完整視窗的結果清單不會插入收藏夾或歷史記錄的回憶項目。這些基於個人使用習慣的結果只保留在快速視窗和內嵌視窗中；完整視窗保持已啟用搜尋提供者的常規相關性順序。</p><p><strong>結果表格列順序</strong> —— 跟設定裏其它地方(見<a href="./favorites.html">收藏夾</a>)同一套排序列表：把結果表格裏的某一列(名稱、路徑、修改時間，或任何插件新增的列)左移或右移。只影響表格視圖的結果列表——精簡列表視圖裏沒有列可以排序。</p><p><strong>側邊欄篩選順序</strong> —— 同樣的機制，調整側邊欄篩選分組(類型、修改時間，以及任何插件新增的分組) 的先後順序。</p><p><strong>動作選單分組順序</strong> —— 同樣的機制，調整<a href="./../actions-and-preview.html#動作選單">動作選單</a>裏各個分組的先後順序：內置動作分組，以及每個往動作選單裏貢獻內容的插件各一個分組(比如自訂動作，或 Windows 系統的右鍵選單)。還沒加入這個列表的分組會按自然順序排列(內置分組在前，插件分組按各自貢獻的先後順序排在後面)。</p><p>點擊結果表格的列標題排序會在三種狀態間循環:升序、降序，第三次點擊會重置回預設的相關性排序(表頭上的排序箭頭也會消失)。這個排序只在 Lertaro 運行期間有效——退出應用(不只是關閉視窗)後下次打開會恢復預設排序，跟上面永久保存的列/側邊欄順序不一樣。</p><h2 id="預覽視窗" tabindex="-1">預覽視窗 <a class="header-anchor" href="#預覽視窗" aria-label="Permalink to &quot;預覽視窗&quot;">​</a></h2><ul><li><strong>預覽視窗寬度(像素)</strong> —— 範圍 250–900px。</li><li><strong>預覽視窗高度(像素)</strong> —— 範圍 250–1200px，預設值不會在常見顯示器上顯得過高。</li><li><strong>重置預覽視窗設定</strong> 按鈕。</li></ul><p>預覽視窗的尺寸是固定的，不受當前結果數量影響——它不是一個隨內容變化的自適應大小。預覽面板具體如何定位，見<a href="./../actions-and-preview.html">動作選單與預覽</a>。</p><h2 id="快速導航" tabindex="-1">快速導航 <a class="header-anchor" href="#快速導航" aria-label="Permalink to &quot;快速導航&quot;">​</a></h2><p>設定<a href="./../hotkeys.html#快速導航-滑鼠">快速導航</a>選單根層級各個分組的先後順序——每個貢獻條目的 provider 一個分組(比如收藏夾/歷史記錄/配置好的快捷資料夾、Total Commander 的 Directory Hotlist、Directory Opus 的收藏夾、某個插件自己的快速導航條目)，各自帶一個標題。</p><p><strong>提供者順序</strong> —— 跟設定裏其它地方(見<a href="./favorites.html">收藏夾</a>)同一套上移/下移(也可以拖動)排序列表：把某個 provider 上移或下移，就能改變它的分組相對其它分組出現的位置。這裏只列出插件組件當前處於啓用狀態的 provider——在<a href="./plugins.html">插件</a>裏整體禁用的組件從一開始就不會成為選單候選項，也就沒有順序可調。</p><h2 id="預覽與縮略圖" tabindex="-1">預覽與縮略圖 <a class="header-anchor" href="#預覽與縮略圖" aria-label="Permalink to &quot;預覽與縮略圖&quot;">​</a></h2><p>兩個各自獨立的優先級排序列表，分別決定各自領域裏哪個提供者優先被嘗試——正常情況下完全由每個提供者自身固定的內置優先級決定，除了整體禁用某個提供者以外，沒有別的辦法能改變這個順序。</p><p><strong>檔案預覽提供者順序</strong> —— 針對<a href="./../actions-and-preview.html#quicklook-預覽">檔案預覽提供者</a>(比如 <a href="./../actions-and-preview.html#通過-quicklook-的外部預覽-可選">QuickLook Bridge</a>插件會把自己的優先級設得比所有內置預覽類型都高)。跟設定裏其它地方(見<a href="./favorites.html">收藏夾</a>)同一套上移/下移(也可以拖動)排序列表：把某個提供者上移，就能讓它始終優先於排在它下面的提供者，不管它自己內置的優先級是多少。這裏只列出插件組件當前處於啓用狀態的提供者——在<a href="./plugins.html">插件</a>裏整體禁用的組件反正也不會真正參與任何預覽。</p><p><strong>縮略圖提供者順序</strong> —— 同樣的機制，針對的是結果列表本身顯示的圖示/縮略圖(而不是預覽面板)—— 目前內置的提供者只有一個，等以後有多個插件都實現了自訂縮略圖提供者時，這個順序才真正有意義。</p>',31)])])}const u=r(e,[["render",n]]);export{c as __pageData,u as default};
